// Debug builds talk to Metro and a local backend over `adb reverse` (http://localhost). Expo's template
// allows cleartext to EVERY host in debug; this narrows it to loopback via a debug-only network security
// config. Release builds get nothing from here: no cleartext at all (Android's default for targetSdk >= 28).
// It also drops OTA code signing from DEBUG builds only (see the manifest comment below).
const fs = require('fs')
const path = require('path')
const { withDangerousMod } = require('expo/config-plugins')

const XML = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/withDevNetworkSecurity.js (debug builds only). -->
<network-security-config>
  <base-config cleartextTrafficPermitted="false" />
  <domain-config cleartextTrafficPermitted="true">
    <domain includeSubdomains="false">localhost</domain>
    <domain includeSubdomains="false">127.0.0.1</domain>
    <domain includeSubdomains="false">10.0.2.2</domain>
  </domain-config>
</network-security-config>
`

const MANIFEST = `<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools">

    <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW"/>

    <application
        android:usesCleartextTraffic="false"
        android:networkSecurityConfig="@xml/network_security_config_debug"
        tools:targetApi="28"
        tools:ignore="GoogleAppIndexingWarning"
        tools:replace="android:usesCleartextTraffic">
        <!-- Dev clients load JS from Metro and never apply OTA updates (docs/ota-updates.md); without these the
             dev launcher demands a code-signed Metro manifest, i.e. the OTA private key on every dev machine. -->
        <meta-data android:name="expo.modules.updates.CODE_SIGNING_CERTIFICATE" tools:node="remove" />
        <meta-data android:name="expo.modules.updates.CODE_SIGNING_METADATA" tools:node="remove" />
    </application>
</manifest>
`

module.exports = function withDevNetworkSecurity(config) {
  return withDangerousMod(config, [
    'android',
    async cfg => {
      const debug = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'debug')
      fs.mkdirSync(path.join(debug, 'res', 'xml'), { recursive: true })
      fs.writeFileSync(path.join(debug, 'res', 'xml', 'network_security_config_debug.xml'), XML)
      fs.writeFileSync(path.join(debug, 'AndroidManifest.xml'), MANIFEST)
      return cfg
    },
  ])
}
